"""Workspace configuration: where wakil state lives inside a knowledge base.

All wakil state for a workspace is kept in a `.wakil/` directory at the
knowledge-base root: a YAML config file and a SQLite database. Markdown files
remain the source of truth; `.wakil/` is operational state only.
"""

from __future__ import annotations

from pathlib import Path

import yaml
from pydantic import BaseModel, Field

WAKIL_DIR = ".wakil"
CONFIG_FILENAME = "config.yaml"
DATABASE_FILENAME = "wakil.db"

# Top-level files treated as high-priority workspace context when present.
SPECIAL_FILES = ("README.md", "AGENTS.md", "SCHEMA.md", "RESOLVER.md")


class WorkspaceConfig(BaseModel):
    """Persisted per-workspace settings."""

    name: str
    root_path: Path
    git_remote: str | None = None
    qmd_enabled: bool = False
    ingest_directory: str = Field(default="sources")
    generated_directory: str = Field(default="drafts")

    @property
    def wakil_dir(self) -> Path:
        return self.root_path / WAKIL_DIR

    @property
    def database_path(self) -> Path:
        return self.wakil_dir / DATABASE_FILENAME

    @property
    def config_path(self) -> Path:
        return self.wakil_dir / CONFIG_FILENAME

    def save(self) -> None:
        self.wakil_dir.mkdir(parents=True, exist_ok=True)
        # Operational state stays out of the knowledge base's git history.
        gitignore = self.wakil_dir / ".gitignore"
        if not gitignore.exists():
            gitignore.write_text("*\n", encoding="utf-8")
        data = self.model_dump(mode="json")
        self.config_path.write_text(yaml.safe_dump(data, sort_keys=False), encoding="utf-8")

    @classmethod
    def load(cls, root: Path) -> WorkspaceConfig:
        config_path = root / WAKIL_DIR / CONFIG_FILENAME
        data = yaml.safe_load(config_path.read_text(encoding="utf-8"))
        # The workspace may have been moved or checked out elsewhere; trust
        # the directory the config was found in over the stored path.
        data["root_path"] = str(root)
        return cls.model_validate(data)


def is_initialized(root: Path) -> bool:
    return (root / WAKIL_DIR / CONFIG_FILENAME).is_file()


def find_workspace_root(start: Path) -> Path | None:
    """Walk upward from `start` looking for an initialized workspace."""
    current = start.resolve()
    for candidate in (current, *current.parents):
        if is_initialized(candidate):
            return candidate
    return None

"""Local registry of known workspaces, so the CLI can address them by name.

Stored at ~/.config/wakil/workspaces.yaml (XDG_CONFIG_HOME aware) as a flat
name -> root_path mapping. `wakil init` registers the workspace; `-w <name>`
resolves through it. The registry is a convenience index only — each
workspace stays fully self-contained in its own `.wakil/` directory.
"""

import os
from pathlib import Path

import yaml

REGISTRY_FILENAME = "workspaces.yaml"


def registry_path() -> Path:
    config_home = os.environ.get("XDG_CONFIG_HOME")
    base = Path(config_home) if config_home else Path.home() / ".config"
    return base / "wakil" / REGISTRY_FILENAME


def _load() -> dict[str, str]:
    path = registry_path()
    if not path.is_file():
        return {}
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8"))
    except yaml.YAMLError:
        return {}
    return data if isinstance(data, dict) else {}


def register_workspace(name: str, root: Path) -> None:
    data = _load()
    data[name] = str(root)
    path = registry_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(yaml.safe_dump(data, sort_keys=True), encoding="utf-8")


def lookup_workspace(name: str) -> Path | None:
    value = _load().get(name)
    return Path(value) if value else None


def list_workspaces() -> dict[str, str]:
    return _load()

"""Markdown file discovery and metadata extraction."""

import hashlib
import re
from dataclasses import dataclass, field
from pathlib import Path

import frontmatter

# Directories never indexed as knowledge content.
SKIPPED_DIRS = {".git", ".wakil", ".obsidian", "node_modules", ".venv"}

_H1_RE = re.compile(r"^#\s+(.+?)\s*$", re.MULTILINE)


@dataclass
class MarkdownFile:
    """Metadata extracted from one Markdown file in the knowledge base."""

    path: Path  # relative to the workspace root
    title: str
    content_hash: str
    metadata: dict = field(default_factory=dict)


def discover_markdown_files(root: Path) -> list[Path]:
    """Return workspace-relative paths of all indexable Markdown files."""
    results: list[Path] = []
    for path in sorted(root.rglob("*.md")):
        relative = path.relative_to(root)
        if any(part in SKIPPED_DIRS or part.startswith(".") for part in relative.parts[:-1]):
            continue
        results.append(relative)
    return results


def read_markdown_file(root: Path, relative_path: Path) -> MarkdownFile:
    """Parse one Markdown file into indexable metadata.

    Malformed frontmatter must not break indexing: fall back to treating the
    whole file as plain content.
    """
    full_path = root / relative_path
    raw = full_path.read_bytes()
    content_hash = hashlib.sha256(raw).hexdigest()
    text = raw.decode("utf-8", errors="replace")

    try:
        post = frontmatter.loads(text)
        metadata = dict(post.metadata)
        body = post.content
    except Exception:
        metadata = {}
        body = text

    title = _extract_title(metadata, body, relative_path)
    return MarkdownFile(
        path=relative_path, title=title, content_hash=content_hash, metadata=metadata
    )


def _extract_title(metadata: dict, body: str, relative_path: Path) -> str:
    for key in ("title", "name"):
        value = metadata.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    match = _H1_RE.search(body)
    if match:
        return match.group(1)
    return relative_path.stem
